using System;using System.IO;using System.Linq;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Threading;using System.Runtime.InteropServices;using RingTimer;
class FeatureCapture {
 [DllImport("user32.dll")]static extern bool SetCursorPos(int x,int y);
 [DllImport("user32.dll")]static extern bool GetCursorPos(out P p);struct P{public int X,Y;}
 static void Wait(int ms){var f=new DispatcherFrame();var t=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(ms)};t.Tick+=(s,e)=>{t.Stop();f.Continue=false;};t.Start();Dispatcher.PushFrame(f);}
 static void Screen(string path,int x,int y,int w,int h){using(var b=new System.Drawing.Bitmap(w,h)){using(var g=System.Drawing.Graphics.FromImage(b)){g.CopyFromScreen(x,y,0,0,new System.Drawing.Size(w,h));}b.Save(path);}}
 [STAThread]static void Main(string[] args){Native.SetProcessDPIAware();string root=args[0];Directory.CreateDirectory(root);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var prefs=new AppearanceSettings(null);Theme.ApplyGlobalResources(app);var engine=new TimerEngine(new TimerState(),()=>DateTime.UtcNow);var data=new StatsStore(null);DateTime today=DateTime.Today;
 for(int i=0;i<91;i++){if(i%5==0)continue;var start=today.AddDays(-i).AddHours(10).ToUniversalTime();engine.State.PendingStats.Add(new CompletedSession{Id="demo-work-"+i,Kind="work",Spans={new FocusSpan{StartUtc=start.Ticks,EndUtc=start.AddMinutes(15+i%5*20).Ticks}}});engine.State.PendingStats.Add(new CompletedSession{Id="demo-rest-"+i,Kind="rest",Spans={new FocusSpan{StartUtc=start.AddHours(2).Ticks,EndUtc=start.AddHours(2).AddMinutes(5+i%4*5).Ticks}}});}data.Collect(engine.State);
 var timer=new TimerFeature(engine,()=>{});var stats=new StatsFeature(data);var menu=new MenuWindow(new FeatureRegistry(timer,stats),()=>{},()=>{},prefs){Left=-2000,Top=30,AnimationsEnabled=false};menu.Reveal();
 foreach(string lang in new[]{"zh-CN","en"}){prefs.Language=lang;Theme.Apply(true,null,null,null);menu.ShowHome();Wait(280);Theme.Snapshot(menu,Path.Combine(root,"home-"+lang+".png"),1.5);menu.OpenFeature("timer");Wait(280);Theme.Snapshot(menu,Path.Combine(root,"timer-"+lang+".png"),1.5);Theme.Apply(false,null,null,null);Wait(100);Theme.Snapshot(menu,Path.Combine(root,"light-"+lang+".png"),1.5);Theme.Apply(true,null,null,null);menu.OpenFeature("stats");((StatsPanel)stats.View).SelectView("calendar");Wait(280);Theme.Snapshot(menu,Path.Combine(root,"heatmap-"+lang+".png"),1.5);((StatsPanel)stats.View).SelectView("total");Wait(280);Theme.Snapshot(menu,Path.Combine(root,"totals-"+lang+".png"),1.5);menu.OpenAppearanceSettings();Wait(280);Theme.Snapshot(menu,Path.Combine(root,"appearance-"+lang+".png"),1.5);menu.OpenSoundSettings();Wait(280);Theme.Snapshot(menu,Path.Combine(root,"sound-"+lang+".png"),1.5);}
 // Controlled desktop backdrop allows Windows composition to be captured faithfully.
 var canvas=new Grid{Background=new LinearGradientBrush(Color.FromRgb(30,105,135),Color.FromRgb(122,78,128),30)};for(int i=0;i<7;i++){var line=new TextBlock{Text="FOCUS   /   CREATE   /   REFLECT",FontSize=24,Foreground=Brushes.White,Opacity=.06,Margin=new Thickness(40,i*90+30,0,0),VerticalAlignment=VerticalAlignment.Top};canvas.Children.Add(line);}
 var host=new Window{Left=60,Top=40,Width=900,Height=800,WindowStyle=WindowStyle.None,Content=canvas,ShowInTaskbar=false,Topmost=true};host.Show();menu.Owner=host;menu.Topmost=true;prefs.Language="en";menu.ShowHome();menu.MovePixels(250,160);menu.Activate();Wait(350);var bounds=menu.PixelBounds;int capX=bounds.Left-20,capY=bounds.Top-20,capW=bounds.Width+40,capH=bounds.Height+40;double scale=bounds.Width/344.0;var bubble=new Bubble{Owner=host,Topmost=true};bubble.Show();bubble.MovePixels(bounds.Right-(int)(60*scale),bounds.Bottom-(int)(60*scale));menu.AnchorBounds=()=>bubble.PixelBounds;P original;GetCursorPos(out original);
 try{menu.AnimationsEnabled=true;menu.ClosePanel();Wait(350);Directory.CreateDirectory(Path.Combine(root,"opening"));for(int i=0;i<65;i++){if(i==8)menu.Reveal();if(i==43)menu.ClosePanel();Wait(33);Screen(Path.Combine(root,"opening",i.ToString("000")+".png"),capX,capY,capW,capH);}
 menu.Reveal();Wait(350);Directory.CreateDirectory(Path.Combine(root,"pointer"));for(int i=0;i<75;i++){double t=i/74.0;int x=bounds.Left+(int)((35+230*t)*scale),y=bounds.Top+(int)((140+70*Math.Sin(t*Math.PI*2))*scale);SetCursorPos(x,y);Wait(33);Screen(Path.Combine(root,"pointer",i.ToString("000")+".png"),capX,capY,capW,capH);File.AppendAllText(Path.Combine(root,"pointer-coordinates.txt"),(x-capX)+","+(y-capY)+Environment.NewLine);}
 bubble.Hide();menu.AnchorBounds=null;menu.OpenAppearanceSettings();Wait(350);foreach(int n in new[]{15,75}){prefs.Transparency=n;Wait(350);var b=menu.PixelBounds;Screen(Path.Combine(root,"glass-"+n+".png"),b.Left,b.Top,b.Width,b.Height);}
 }finally{SetCursorPos(original.X,original.Y);bubble.Close();menu.Disposing=true;menu.Close();host.Close();prefs.Dispose();app.Shutdown();}File.WriteAllText(Path.Combine(root,"done.txt"),"Captured bilingual feature pages and native desktop animations");}
}
